'lascombes|2005':{blend:{CS:52,ME:45,PV:3},yld:40,alc:13.5,note:'ASSEMBLAGE / BLEND VENDANGES / HARVEST VINIFICATION / WINEMAKING DEGRÉ ALCOOLIQUE / ALCOHOL CONTENT RENDEMENT / YIELD ÉLEVAGE / AGEING 52% Cabernet Sauvignon, 45% Merlot, 3% petit Verdot. Hand harvesting in several passes, according to the level of maturity of the plots.',taste:'s quotidiennes. Gentle vinification by infusion. Cold maceration. Maceration period from 30 to 35 days decided by daily tastings. 13,5% vol. 40 hl/ha En barriques. In barrels. Château Lascombes GRAND VIN — MARGAUX - 2 e CRU CLASSÉ EN 1855 2OO5',src:'Lascombes_FT_2005.pdf'},
'lascombes|2006':{blend:{CS:50,ME:45,PV:5},yld:36,note:'ASSEMBLAGE / BLEND VENDANGES / HARVEST VINIFICATION / WINEMAKING DEGRÉ ALCOOLIQUE / ALCOHOL CONTENT RENDEMENT / YIELD ÉLEVAGE / AGEING 50% Cabernet Sauvignon, 45% Merlot, et 5% petit Verdot. Hand harvesting in several passes, according to the level of maturity of the plots.',taste:'s quotidiennes. Gentle vinification by infusion. Cold maceration. Maceration period from 30 to 35 days decided by daily tastings. 13% vol. 36 hl/ha En barriques. In barrels. Château Lascombes GRAND VIN — MARGAUX - 2 e CRU CLASSÉ EN 1855 2OO6',src:'Lascombes_FT_2006.pdf'},
'lascombes|2007':{blend:{CS:50,ME:45,PV:5},yld:40.5,note:'ASSEMBLAGE / BLEND VENDANGES / HARVEST VINIFICATION / WINEMAKING DEGRÉ ALCOOLIQUE / ALCOHOL CONTENT RENDEMENT / YIELD ÉLEVAGE / AGEING 50% Cabernet Sauvignon, 45% Merlot, 5% petit Verdot. Hand harvesting in several passes, according to the level of maturity of the plots.',taste:'s quotidiennes. Gentle vinification by infusion. Cold maceration. Maceration period from 30 to 35 days decided by daily tastings. 13% vol. 40,5 hl/ha En barriques. In barrels. Château Lascombes GRAND VIN — MARGAUX - 2 e CRU CLASSÉ EN 1855 2OO7',src:'Lascombes_FT_2007.pdf'},
'lascombes|2008':{blend:{CS:50,ME:47,PV:3},yld:43,note:'ASSEMBLAGE / BLEND VENDANGES / HARVEST VINIFICATION / WINEMAKING DEGRÉ ALCOOLIQUE / ALCOHOL CONTENT RENDEMENT / YIELD ÉLEVAGE / AGEING 50% Cabernet Sauvignon, 47% Merlot, et 3% petit Verdot. Hand harvesting in several passes, according to the level of maturity of the plots.',taste:'s quotidiennes. Gentle vinification by infusion. Cold maceration. Maceration period from 30 to 35 days decided by daily tastings. 13% vol. 43 hl/ha En barriques. In barrels. Château Lascombes GRAND VIN — MARGAUX - 2 e CRU CLASSÉ EN 1855 2OO8',src:'Lascombes_FT_2008.pdf'},
